marta: ```js
// JS snippet: AbortController + retry
async function withRetry(callFn, attempts = 4) {
  for (let i = 0; i < attempts; i++) {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 15000);
    try {
      const resp = await callFn({ signal: controller.signal });
      clearTimeout(timeout);
      if (resp.status !== 429) return resp;
      const ra = resp.headers.get('Retry-After');
      if (ra) await new Promise(r => setTimeout(r, Number(ra) * 1000));
      else await new Promise(r => setTimeout(r, Math.min(1000 * 2 ** i, 10000)));
    } catch (e) {
      clearTimeout(timeout);
      if (e.name === 'AbortError') throw e; // bubble client timeouts
      if (i === attempts - 1) throw e;
    }
  }
}
```

